        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '39048e32-fc12-45dd-a194-c7e1af81f01e'
        AND charge_id = 1131209;
   
    RETURN;
END IF;

END IF;

